'use strict';
const timelineBeforeSceneResize=renderTimeline;renderTimeline=function(){timelineBeforeSceneResize();document.querySelectorAll('.timeline-clip.scene[data-scene-index]').forEach(el=>{const s=project.scenes[+el.dataset.sceneIndex],edge=el.querySelector('.clip-edge.right');if(!s||!edge)return;edge.title='Drag to change scene length';edge.setAttribute('aria-label','Resize '+s.name);el.querySelector('.clip-edge.left').hidden=true;edge.onpointerdown=e=>{if(e.button||recording||window.editorTaskBusy)return;e.preventDefault();e.stopImmediatePropagation();stop();const x=e.clientX,start=s.duration,label=el.querySelector('.clip-name'),original=label.textContent;let duration=start;edge.setPointerCapture(e.pointerId);timelineDrag={mode:'scene-resize'};edge.onpointermove=event=>{duration=clamp(Math.round((start+(event.clientX-x)/timelineZoom)*20)/20,1,60);el.style.width=duration*timelineZoom+'px';label.textContent=s.name+' · '+duration.toFixed(2)+'s'};const finish=cancel=>{edge.onpointermove=edge.onpointerup=edge.onpointercancel=null;timelineDrag=null;if(!cancel&&duration!==start){const si=sceneIndex,t=time;sceneIndex=project.scenes.indexOf(s);if(typeof planSceneHeadResize==='function'){try{Object.assign(project,planSceneHeadResize(s,0,duration));save();hydrateAudio();toast('Scene length: '+duration.toFixed(2)+'s')}catch(error){toast(error.message)}}else if(changeSceneDuration(s,duration))toast('Scene length: '+s.duration.toFixed(2)+'s');sceneIndex=si;time=Math.min(t,current().duration)}label.textContent=original;render()};edge.onpointerup=()=>finish(false);edge.onpointercancel=()=>finish(true)};edge.addEventListener('pointerdown',e=>e.stopPropagation());})};
const sceneResizeStyle=document.createElement('style');sceneResizeStyle.textContent='.timeline-clip.scene .clip-edge.right{width:13px;z-index:12;cursor:ew-resize;background:#c9b6ff77}.timeline-clip.scene .scene-transition-point{right:14px}';document.head.append(sceneResizeStyle);renderTimeline();
